  "summary": "The code suffers from critical security and performance flaws, primarily due to synchronous, unbounded, and unvalidated outbound requests. The overall health is poor, requiring refactoring to asynchronous patterns, strict URL validation, and robust error handling.",
  "fixed_code": "import requests\nfrom flask import Flask, jsonify, request\nfrom urllib.parse import urlparse\n\napp = Flask(__name__)\n\nREQUEST_TIMEOUT = 5\nALLOWED_DOMAINS = {'example.com', 'trusted.org'}\n\ndef is_safe_url(url: str) -> bool:\n    try:\n        parsed = urlparse(url)\n        return parsed.netloc in ALLOWED_DOMAINS\n    except:\n        return False\n\n@app.route(\"/link-preview\")\ndef link_preview() -> Flask.response_class:\n    \"\"\"Fetches metadata for a given URL. Expects 'url' query parameter. Returns status code, content size, and content type.\"\"\"\n    url = request.args.get(\"url\", \"\")\n    if not url.startswith(\"http\") or not is_safe_url(url):\n        return jsonify(error=\"Invalid or forbidden URL\"), 400\n    \n    try:\n        with requests.get(url, timeout=REQUEST_TIMEOUT, stream=True) as resp:\n            resp.raise_for_status()\n            content_length = int(resp.headers.get('Content-Length', 0))\n            if content_length > 1024 * 1024:  # 1MB limit\n                return jsonify(error=\"Payload too large\"), 413\n            return jsonify(status=resp.status_code, size=len(resp.content), type=resp.headers.get(\"Content-Type\"))\n    except requests.exceptions.RequestException as e:\n        return jsonify(error=str(e)), 502"
